require_once __DIR__.'/includes/admin_check.php';require_admin();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$s=db()->prepare("SELECT * FROM services WHERE id=?");$s->execute([$id]);$a=$s->fetch();if(!$a){http_response_code(404);exit('Không tìm thấy gói dịch vụ');}$err='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$n=trim($_POST['name']??'');$price=$_POST['price']??'';$url=trim($_POST['contact_url']??'');if(!$n||!is_numeric($price)||(float)$price<0||($url&&!filter_var($url,FILTER_VALIDATE_URL)))$err='Thông tin không hợp lệ.';else{db()->prepare("UPDATE services SET name=?,category=?,description=?,price=?,duration=?,contact_url=?,status=?,sort_order=? WHERE id=?")->execute([$n,trim($_POST['category']??''),trim($_POST['description']??''),(float)$price,trim($_POST['duration']??''),$url?:null,$_POST['status']==='active'?'active':'hidden',(int)($_POST['sort_order']??0),$id]);$s=db()->prepare("SELECT * FROM services WHERE id=?");$s->execute([$id]);$a=$s->fetch();flash('Đã cập nhật gói dịch vụ.');}}$pageTitle='Sửa dịch vụ';require __DIR__.'/includes/header.php';?><div class="formbox"><h1>Chỉnh sửa gói dịch vụ</h1><p class="error"><?=e($err)?></p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Tên</label><input name="name" required value="<?=e($a['name'])?>"><label>Danh mục</label><input name="category" value="<?=e($a['category'])?>"><label>Mô tả</label><textarea name="description"><?=e($a['description'])?></textarea><label>Giá VND</label><input type="number" name="price" min="0" step="1000" value="<?=e((string)$a['price'])?>" required><label>Thời hạn</label><input name="duration" value="<?=e($a['duration'])?>"><label>Link liên hệ</label><input type="url" name="contact_url" value="<?=e($a['contact_url'])?>"><label>Trạng thái</label><select name="status"><option value="active" <?=$a['status']==='active'?'selected':''?>>Hiển thị</option><option value="hidden" <?=$a['status']==='hidden'?'selected':''?>>Ẩn</option></select><label>Thứ tự</label><input type="number" name="sort_order" value="<?=e((string)$a['sort_order'])?>"><button class="btn">Cập nhật</button></form></div></main></body></html>